        if char_in != char_out:
            print(f"  Position {j}: '{char_in}' -> '{char_out}'")
    # Check if output is longer (new characters added)
    if len(out) > len(inp):
        print(f"  Added characters: {out[len(inp):]}")
    elif len(out) < len(inp):
        print(f"  Removed characters: {inp[len(out):]}")

